<template>
  <div class="q-pa-md">
    <q-btn
      flat
      icon="arrow_back"
      label="BACK TO LOGS"
      color="primary"
      @click="goBack"
      class="q-mb-lg text-weight-bold"
    />

    <div v-if="log" class="container page-height-limit">
      <!-- Error Card with Badge -->
      <div class="q-mb-lg">
        <div class="row items-center q-gutter-md q-mb-md">
          <!-- Severity Badge -->
          <q-badge
            rounded
            :color="getSeverityBgColor(log.level)"
            :text-color="getSeverityTextColor(log.level)"
            class="severity-badge q-py-sm q-px-lg"
          >
            <q-icon :name="getSeverityIcon(log.level)" size="16px" class="q-mr-xs" />
            <span class="text-weight-bold">{{ log.level }}</span>
          </q-badge>

          <!-- Service & ID -->
          <div class="col">
            <div class="text-subtitle2 dark-readable">
              {{ formatAbsoluteTime(log.timestamp) }}
              <q-icon name="circle" size="4px" class="q-mx-sm" />
              <strong>{{ log.service || 'System' }}</strong>
              <q-icon name="circle" size="4px" class="q-mx-sm" />
              ID: {{ log.id?.substring(0, 8) }}
            </div>
          </div>
        </div>

        <!-- Main Message Card -->
        <q-card flat bordered class="message-card back-white">
          <q-card-section class="q-pa-lg">
            <div class="text-body1 text-weight-medium" style="white-space: pre-wrap; word-break: break-word;">
              {{ extractMainMessage(log) }}
            </div>
          </q-card-section>
        </q-card>
      </div>

      <!-- Metadata JSON Section -->
      <q-card flat bordered class="q-mb-lg back-white">
        <q-card-section class="highlighted-back q-pa-md">
          <div class="text-h6 text-weight-bold q-mb-md">
            <q-icon name="code" size="20px" class="q-mr-sm" />
            Log Details
          </div>
        </q-card-section>

        <q-separator />

        <q-card-section class="q-pa-none">
          <div class="relative-position">
            <pre class="json-formatter q-pa-md" v-html="highlightJSON(formatLogMetadataJSON(log))"></pre>
            <div class="absolute-top-right q-pa-sm">
              <q-btn
                flat
                dense
                round
                icon="content_copy"
                @click="copyToClipboard(formatLogMetadataJSON(log))"
                size="md"
                style="background: rgba(0,0,0,0.3); color: white;"
              >
                <q-tooltip>Copy JSON</q-tooltip>
              </q-btn>
            </div>
          </div>
        </q-card-section>
      </q-card>

    </div>

    <div v-else class="text-center q-pa-xl text-grey-7">
      <q-icon name="error_outline" size="64px" />
      <div class="text-h6 q-mt-md">Log not found</div>
      <div class="text-body2">The log entry details are missing or have expired.</div>
      <q-btn flat color="primary" label="Back to Logs" @click="goBack" class="q-mt-md" />
    </div>
  </div>
</template>

<script setup lang="ts">
import { notify } from 'src/components/notifications/notify';
import { ref, onMounted } from 'vue';
import { useRouter } from 'vue-router';
import { formatDistanceToNow, format, parseISO } from 'date-fns';
import { useQuasar } from 'quasar';
const router = useRouter();
const $q = useQuasar();
const log = ref<any>(null);

onMounted(() => {
  // Retrieve log data from router state
  const state = history.state;
  if (state && state.log) {
    log.value = JSON.parse(JSON.stringify(state.log)); // Clone to avoid ref issues
  } else {
    // Ideally fetch from API by ID if available, but for now show error
    console.warn('No log data found in history state');
  }
});

const goBack = () => {
  if (window.history.length > 1) {
    router.back();
  } else {
    router.push('/settings/event-logs');
  }
};

// Helper functions (reused from ActivityLogs.vue - ideally move to composable)
const formatRelativeTime = (timestamp: string): string => {
  try {
    return formatDistanceToNow(parseISO(timestamp), { addSuffix: true });
  } catch (error) {
    return timestamp;
  }
};

const formatAbsoluteTime = (timestamp: string): string => {
  try {
    return format(parseISO(timestamp), 'MMM dd, yyyy HH:mm:ss');
  } catch (error) {
    return timestamp;
  }
};

const getSeverityColor = (severity: string): string => {
  const colors: Record<string, string> = {
    ERROR: 'negative',
    WARN: 'warning',
    INFO: 'primary',
    DEBUG: 'grey-7',
  };
  return colors[severity] || 'grey';
};

const getStructuredLog = (row: any): any | null => {
  if (!row.log) return null;
  try {
    if (typeof row.log === 'string') return JSON.parse(row.log);
    if (typeof row.log === 'object') return row.log;
  } catch (error) { return null; }
  return null;
};

const getDisplayMessage = (row: any): string => {
  const structuredLog = getStructuredLog(row);
  if (structuredLog && structuredLog.message) return structuredLog.message;
  return row.message || 'No message';
};

const getFormattedStructuredLog = (row: any): string => {
  const structuredLog = getStructuredLog(row);
  if (structuredLog) return JSON.stringify(structuredLog, null, 2);
  if (row.log) {
    if (typeof row.log === 'string') {
      try { return JSON.stringify(JSON.parse(row.log), null, 2); } catch { return row.log; }
    }
    return JSON.stringify(row.log, null, 2);
  }
  return row.message;
};

const parseLogMessage = (message: string): any | null => {
  const parts = message.split(' - ');
  if (parts.length >= 4) {
    const [level, time, logger, status, ...rest] = parts;
    if (['INFO', 'ERROR', 'WARN', 'DEBUG'].includes(level) && time.includes(':')) {
      return { level, time, logger, status, message: rest.join(' - ') };
    }
  }
  return null;
};

const copyToClipboard = async (text: string) => {
  try {
    await navigator.clipboard.writeText(text);
    notify.success('Copied to clipboard', { duration: 1500 });
  } catch (error) {
    notify.error('Failed to copy');
  }
};

// New helper functions for improved detail page layout
const getSeverityIcon = (level: string): string => {
  const icons: Record<string, string> = {
    ERROR: 'error_outline',
    WARN: 'warning_outline',
    INFO: 'info',
    DEBUG: 'bug_report',
  };
  return icons[level] || 'info';
};

const getSeverityBgColor = (level: string): string => {
  const colors: Record<string, string> = {
    ERROR: 'negative',
    WARN: 'warning',
    INFO: 'primary',
    DEBUG: 'grey-7',
  };
  return colors[level] || 'grey';
};

const getSeverityTextColor = (level: string): string => {
  return 'white';
};

const extractMainMessage = (logEntry: any): string => {
  // Try to extract the main message from various possible locations
  if (logEntry.message) return logEntry.message;

  const structured = getStructuredLog(logEntry);
  if (structured && structured.message) return structured.message;

  if (logEntry.log) {
    if (typeof logEntry.log === 'string') {
      try {
        const parsed = JSON.parse(logEntry.log);
        if (parsed.message) return parsed.message;
      } catch (e) {
        return logEntry.log;
      }
    }
    return typeof logEntry.log === 'string' ? logEntry.log : JSON.stringify(logEntry.log);
  }

  return 'No message available';
};

const getParsedErrorDetails = (logEntry: any): Record<string, any> | null => {
  const structured = getStructuredLog(logEntry);
  if (!structured) return null;

  const details: Record<string, any> = {};

  // Extract common error detail fields
  const errorFields = [
    'error', 'exception', 'stack', 'trace', 'status', 'code',
    'error_code', 'error_message', 'details', 'traceback'
  ];

  errorFields.forEach(field => {
    if (structured[field] && structured[field] !== structured.message) {
      details[field] = structured[field];
    }
  });

  // Return details only if we found any
  return Object.keys(details).length > 0 ? details : null;
};

const getStructuredDetails = (logEntry: any): Record<string, any> | null => {
  const details: Record<string, any> = {};

  // First, try to extract from nested structured log
  const structured = getStructuredLog(logEntry);
  if (structured && typeof structured === 'object') {
    // Priority 1: Error/exception fields for ERROR/WARN logs
    const errorFields = [
      'error', 'exception', 'stack', 'trace', 'status', 'code',
      'error_code', 'error_message', 'details', 'traceback', 'cause'
    ];

    errorFields.forEach(field => {
      if (structured[field] && structured[field] !== structured.message) {
        details[field] = structured[field];
      }
    });

    // Priority 2: If no error details, extract context information
    if (Object.keys(details).length === 0 && structured.context) {
      // Context has important debugging info: app, component, environment, url, page, userAgent
      const contextData = structured.context;
      details['App'] = contextData.app;
      if (contextData.component) details['Component'] = contextData.component;
      if (contextData.environment) details['Environment'] = contextData.environment;
      if (contextData.url) details['URL'] = contextData.url;
      if (contextData.page) details['Page'] = contextData.page;
    }

    // Priority 3: Show other useful structured fields (only technical debugging fields)
    if (Object.keys(details).length === 0) {
      const usefulFields = [
        'request_id', 'duration', 'response_time', 'latency',
        'http_status', 'status_code', 'module', 'function', 'class',
        'line', 'file', 'endpoint', 'path', 'method'
      ];

      usefulFields.forEach(field => {
        if (structured[field]) {
          details[field] = structured[field];
        }
      });
    }
  }

  // Only add top-level fields if we have error/technical details
  if (Object.keys(details).length === 0) {
    const technicalFields = [
      'request_id', 'duration', 'response_time', 'http_status', 'status_code',
      'endpoint', 'path', 'method', 'error_code', 'status'
    ];

    technicalFields.forEach(field => {
      if (logEntry[field] && field !== 'message' && field !== 'timestamp') {
        details[field] = logEntry[field];
      }
    });
  }

  return Object.keys(details).length > 0 ? details : null;
};

const getFilteredMetadata = (logEntry: any): Record<string, any> => {
  const metadata: Record<string, any> = {};

  // Always add top-level log context fields first
  const topLevelMetadata = [
    'service', 'organization_name', 'id', 'request_id', 'user_id',
    'duration', 'response_time', 'endpoint', 'path', 'method',
    'http_status', 'status_code', 'correlation_id', 'trace_id'
  ];

  topLevelMetadata.forEach(field => {
    if (logEntry[field]) {
      metadata[field] = logEntry[field];
    }
  });

  // Extract context object fields from nested structured log
  const structured = getStructuredLog(logEntry);
  if (structured && typeof structured === 'object' && structured.context) {
    const context = structured.context;
    if (context.app) metadata['app'] = context.app;
    if (context.component) metadata['component'] = context.component;
    if (context.environment) metadata['environment'] = context.environment;
    if (context.url) metadata['url'] = context.url;
    if (context.page) metadata['page'] = context.page;
    if (context.userAgent) metadata['userAgent'] = context.userAgent;
    if (context.appVersion) metadata['appVersion'] = context.appVersion;
    if (context.referrer) metadata['referrer'] = context.referrer;
  }

  // Add other structured fields (but not message, level, timestamp, or error fields)
  if (structured && typeof structured === 'object') {
    const excludeFields = new Set([
      'message', 'level', 'timestamp', 'error', 'exception', 'stack', 'trace',
      'status', 'code', 'error_code', 'error_message', 'details', 'traceback',
      'context', 'cause'
    ]);

    Object.entries(structured).forEach(([key, value]) => {
      if (!excludeFields.has(key) && value !== null && value !== undefined && !metadata[key]) {
        metadata[key] = value;
      }
    });
  }

  return metadata;
};

const formatLabel = (key: string): string => {
  // Convert snake_case or camelCase to readable format
  return key
    .replace(/([A-Z])/g, ' $1') // camelCase -> camel Case
    .replace(/_/g, ' ') // snake_case -> snake case
    .replace(/^\w/, c => c.toUpperCase()) // capitalize first letter
    .trim();
};

const formatValue = (value: any): string => {
  if (value === null || value === undefined) return 'N/A';
  if (typeof value === 'boolean') return value ? 'Yes' : 'No';
  if (typeof value === 'object') return JSON.stringify(value, null, 2);
  return String(value);
};

const formatLogMetadataJSON = (logEntry: any): string => {
  if (!logEntry) return '{}';

  // Create a clean metadata object with essential fields
  const metadata: Record<string, any> = {
    id: logEntry.id,
    timestamp: logEntry.timestamp,
    level: logEntry.level,
    service: logEntry.service,
    organization_name: logEntry.organization_name,
    message: logEntry.message,
  };

  // Add structured log data if available
  const structured = getStructuredLog(logEntry);
  if (structured && typeof structured === 'object') {
    metadata.details = structured;
  }

  // Add context information if available
  if (logEntry.metadata) {
    metadata.metadata = logEntry.metadata;
  }

  return JSON.stringify(metadata, null, 2);
};

const highlightJSON = (jsonStr: string): string => {
  if (!jsonStr) return '';

  return jsonStr
    // Highlight keys (strings followed by colon)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/("(\\u[a-zA-Z0-9]{4}|\\[^u]|[^\\"])*"(\s*:)?)/g, (match) => {
      if (match.endsWith(':')) {
        // Key
        return `<span class="json-key">${match.slice(0, -1)}</span><span class="json-colon">:</span>`;
      } else {
        // String value
        return `<span class="json-string">${match}</span>`;
      }
    })
    // Highlight numbers
    .replace(/:\s*(-?\d+\.?\d*([eE][+-]?\d+)?)/g, (match) => {
      const num = match.split(':')[1].trim();
      return `: <span class="json-number">${num}</span>`;
    })
    // Highlight booleans
    .replace(/:\s*(true|false)/g, (match) => {
      const bool = match.split(':')[1].trim();
      return `: <span class="json-boolean">${bool}</span>`;
    })
    // Highlight null
    .replace(/:\s*null/g, ': <span class="json-null">null</span>')
    // Highlight punctuation
    .replace(/([{}\[\],:])/g, '<span class="json-punctuation">$1</span>')
    // Clean up double-encoded punctuation
    .replace(/&lt;span class="json-punctuation"&gt;/g, '<span class="json-punctuation">')
    .replace(/&lt;\/span&gt;/g, '</span>')
    .replace(/&quot;/g, '"');
};
</script>

